// Draw colorful fish
function drawFish(x, y, color) {
    // Main body
    ctx.fillStyle = color;
    ctx.fillRect(x, y, 20, 10);

    // Tail
    ctx.fillRect(x - 10, y, 10, 8);

    // Eye
    ctx.fillStyle = HIGHLIGHT;
    ctx.fillRect(x + 12, y + 2, 4, 4);

    // Fins
    ctx.fillStyle = ACCENT;
    ctx.fillRect(x - 5, y, 3, 6); // Left fin
    ctx.fillRect(x + 12, y, 3, 6); // Right fin

    // Scale details
    ctx.fillStyle = SHADOW;
    for (let j = 0; j < 5; j++) {
        ctx.fillRect(x + j * 4 - 2, y + 1, 2, 2);
    }
}

