                   len * 0.7, dir + Math.PI/2, depth + 1);
        drawSpiral(x + len * Math.cos(dir), y - len * Math.sin(dir),
                   len * 0.7, dir - Math.PI/2, depth + 1);
        drawSpiral(x - len * Math.sin(dir), y + len * Math.cos(dir),
                   len * 0.7, dir - Math.PI/2, depth + 1);
        drawSpiral(x - len * Math.sin(dir), y + len * Math.cos(dir),
                   len * 0.7, dir + Math.PI/2, depth + 1);
    }
};

