// Draw sky gradient
const SKY_DARK = '#0a0a2a';
const SKY_LIGHT = '#3a3a5a';
const SKY_TRANS = '#5a5a7a';

ctx.fillStyle = SKY_DARK;
ctx.fillRect(0, 0, W, H);

for (let y = 0; y < H; y++) {
    const t = y / H;
    const r = SKY_DARK.r + t * (SKY_LIGHT.r - SKY_DARK.r);
    const g = SKY_DARK.g + t * (SKY_LIGHT.g - SKY_DARK.g);
    const b = SKY_DARK.b + t * (SKY_LIGHT.b - SKY_DARK.b);
    ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
    ctx.fillRect(0, y, W, 1);
}

